class SimpleAppStateEmitter {
    listeners = new Set();
    on(event, listener) {
        if (event === "app-state")
            this.listeners.add(listener);
        return this;
    }
    off(event, listener) {
        if (event === "app-state")
            this.listeners.delete(listener);
        return this;
    }
    removeListener(event, listener) {
        return this.off(event, listener);
    }
    emit(event, payload) {
        if (event !== "app-state")
            return false;
        for (const listener of this.listeners)
            listener(payload);
        return this.listeners.size > 0;
    }
}
/**
 * Singleton emitter for application-state DB changes.
 * The SSE handler subscribes to this via extraEmitters.
 */
const _emitter = new SimpleAppStateEmitter();
export function getAppStateEmitter() {
    return _emitter;
}
export function emitAppStateChange(key, requestSource, owner) {
    const event = {
        source: "app-state",
        type: "change",
        key,
        ...(owner && { owner }),
        ...(requestSource && { requestSource }),
    };
    _emitter.emit("app-state", event);
}
export function emitAppStateDelete(key, requestSource, owner) {
    const event = {
        source: "app-state",
        type: "delete",
        key,
        ...(owner && { owner }),
        ...(requestSource && { requestSource }),
    };
    _emitter.emit("app-state", event);
}
